// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === "string")
  ? csvRaw
  : JSON.stringify(csvRaw);

const lines = text
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Normaliza mínimo para número
  obj.minimo = Number(
    String(obj.minimo).replace(/[^\d]/g, "")
  ) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const clientes = $json.body;
const investimentos = $json.investimentos;

const resultados = clientes.map(cliente => {

  const saldoNum = Number(
    cliente.saldo
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );

  const opcoes = investimentos.filter(
    inv => inv.perfil === cliente.perfil
  );

  const elegiveis = opcoes.filter(
    inv => saldoNum >= inv.minimo
  );

  const recomendacao =
    elegiveis.sort((a, b) => b.minimo - a.minimo)[0]
    || opcoes[0];

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao,
    mensagem: `Olá ${cliente.nome}! Pelo seu perfil ${cliente.perfil}, recomendamos o investimento ${recomendacao.produto} com rentabilidade de ${recomendacao.rentabilidade}.`
  };
});

return [{
  json: {
    ok: true,
    total_clientes: clientes.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];
